package com.fandazi.feature.order;
import java.math.BigDecimal; import java.util.*;
public record OrderResponse(Long id,OrderStatus status,String recipient,String phone,String detail,BigDecimal subtotal,BigDecimal deliveryFee,BigDecimal total,List<Item> items,List<OrderStatus> timeline){ public record Item(Long dishId,String dishName,int quantity,List<Long> optionIds,String optionSummary,BigDecimal unitPrice){} public static OrderResponse from(OrderEntity o){return new OrderResponse(o.getId(),o.getStatus(),o.getAddressRecipient(),o.getAddressPhone(),o.getAddressDetail(),o.getSubtotal(),o.getDeliveryFee(),o.getTotal(),o.getItems().stream().map(i->new Item(i.getDishId(),i.getDishName(),i.getQuantity(),i.getOptionIds(),i.getOptionSummary(),i.getUnitPrice())).toList(),o.getTimeline());} }
